// A replica of the Complianz cookie banner for Echo's tests, written
// fresh from Complianz's public documentation (https://complianz.io/,
// the cmplz_<category> allow or deny cookies and the cmplz-show-banner
// class) and the banner markup of the GPL WordPress plugin
// (complianz-gdpr 7.5.6): window.complianz (its settings),
// window.cmplz_set_cookie, the cmplz-hidden, cmplz-show and
// cmplz-categories-visible classes. It is not Complianz's code.
// Captured 2026-10-26.
//
// The page holds the banner in <template id="replica-banner">; the
// script tag's data-show says when it appears: now, late (after 4 s) or
// never.
(function () {
  "use strict";
  var me = document.currentScript;
  var show = (me && me.getAttribute("data-show")) || "now";
  var cats = ["preferences", "statistics", "marketing"];
  var mounted = false;

  window.complianz = { prefix: "cmplz_", consenttype: "optin", region: "eu", version: "7.5.6", categories: ["functional"].concat(cats) };

  window.cmplz_set_cookie = function (name, value) {
    document.cookie = "cmplz_" + name + "=" + value + "; path=/; max-age=31536000; SameSite=Lax";
  };

  function q(sel) { return document.querySelector(sel); }

  function store(granted) {
    window.cmplz_set_cookie("functional", "allow");
    cats.forEach(function (c) { window.cmplz_set_cookie(c, granted[c] ? "allow" : "deny"); });
    window.cmplz_set_cookie("banner-status", "dismissed");
    var b = q(".cmplz-cookiebanner");
    if (b) {
      b.classList.remove("cmplz-show");
      b.classList.add("cmplz-dismissed");
    }
    var m = q(".cmplz-manage-consent");
    if (m) m.classList.remove("cmplz-hidden");
  }

  function all(v) {
    var g = {};
    cats.forEach(function (c) { g[c] = v; });
    return g;
  }

  function on(sel, fn) {
    var els = document.querySelectorAll(sel);
    for (var i = 0; i < els.length; i++) {
      els[i].addEventListener("click", function (e) { e.preventDefault(); fn(); });
    }
  }

  function mount() {
    if (mounted) return;
    mounted = true;
    if (!q(".cmplz-cookiebanner")) {
      var tpl = document.getElementById("replica-banner");
      if (!tpl) return;
      document.body.appendChild(tpl.content.cloneNode(true));
    }
    var b = q(".cmplz-cookiebanner");
    b.classList.remove("cmplz-hidden");
    b.classList.add("cmplz-show");
    on(".cmplz-accept", function () { store(all(true)); });
    on(".cmplz-deny", function () { store(all(false)); });
    on(".cmplz-view-preferences", function () { b.classList.add("cmplz-categories-visible"); });
    on(".cmplz-save-preferences", function () {
      var g = {};
      cats.forEach(function (c) {
        var el = q(".cmplz-consent-checkbox.cmplz-" + c);
        g[c] = !!(el && el.checked);
      });
      store(g);
    });
    on(".cmplz-manage-consent", function () {
      b.classList.remove("cmplz-dismissed");
      b.classList.add("cmplz-show");
    });
  }

  if (show === "now") {
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", mount);
    else mount();
  } else if (show === "late") {
    setTimeout(mount, 4000);
  }
})();
